use super::stroke::{Cap, Join, Subpath, outline};
use std::io;

/// The golden for each supported fixture. ROUND cap and ROUND join fixtures have none.
fn golden_for(name: &str) -> Option<&'static [u8]> {
    Some(match name {
        "h_butt" => GEOM_H_BUTT,
        "h_square" => GEOM_H_SQUARE,
        "diag_butt" => GEOM_DIAG_BUTT,
        "diag_square" => GEOM_DIAG_SQUARE,
        "api_h_square" => GEOM_API_H_SQUARE,
        "api_diag_square" => GEOM_API_DIAG_SQUARE,
        "poly_miter" => GEOM_POLY_MITER,
        "poly_bevel" => GEOM_POLY_BEVEL,
        "poly_miter_limited" => GEOM_POLY_MITER_LIMITED,
        "ctl_limited_bevel" => GEOM_CTL_LIMITED_BEVEL,
        "poly_miter_fallback" => GEOM_POLY_MITER_FALLBACK,
        "ctl_fallback_bevel" => GEOM_CTL_FALLBACK_BEVEL,
        "poly_miter_sq" => GEOM_POLY_MITER_SQ,
        "o_h_butt" => GEOM_O_H_BUTT,
        "o_h_square" => GEOM_O_H_SQUARE,
        "o_diag_butt" => GEOM_O_DIAG_BUTT,
        "o_diag_square" => GEOM_O_DIAG_SQUARE,
        "o_api_h_square" => GEOM_O_API_H_SQUARE,
        "o_api_diag_square" => GEOM_O_API_DIAG_SQUARE,
        "o_poly_miter" => GEOM_O_POLY_MITER,
        "o_poly_bevel" => GEOM_O_POLY_BEVEL,
        "o_poly_miter_limited" => GEOM_O_POLY_MITER_LIMITED,
        "o_ctl_limited_bevel" => GEOM_O_CTL_LIMITED_BEVEL,
        "o_poly_miter_fallback" => GEOM_O_POLY_MITER_FALLBACK,
        "o_ctl_fallback_bevel" => GEOM_O_CTL_FALLBACK_BEVEL,
        "o_poly_miter_sq" => GEOM_O_POLY_MITER_SQ,
        "o_single_butt_wide" => GEOM_O_SINGLE_BUTT_WIDE,
        "o_poly3_square_w3" => GEOM_O_POLY3_SQUARE_W3,
        "o_poly_bevel_w2" => GEOM_O_POLY_BEVEL_W2,
        "o_dup_points" => GEOM_O_DUP_POINTS,
        _ => return None,
    })
}

fn cap_of(code: u32) -> Option<Cap> {
    match code {
        0x1700 => Some(Cap::Butt),
        0x1701 => Some(Cap::Round),
        0x1702 => Some(Cap::Square),
        _ => None,
    }
}

fn join_of(code: u32) -> Option<Join> {
    match code {
        0x1800 => Some(Join::Miter),
        0x1801 => Some(Join::Round),
        0x1802 => Some(Join::Bevel),
        _ => None,
    }
}

fn points_from_bits(points: &[(u32, u32)]) -> Vec<(f32, f32)> {
    points
        .iter()
        .map(|&(x, y)| (f32::from_bits(x), f32::from_bits(y)))
        .collect()
}

fn error_kind(result: io::Result<Vec<u8>>) -> Option<io::ErrorKind> {
    result.err().map(|error| error.kind())
}

/// The index of the first byte where the two differ, or the shorter length.
fn first_difference(got: &[u8], want: &[u8]) -> Option<usize> {
    got.iter()
        .zip(want)
        .position(|(a, b)| a != b)
        .or_else(|| (got.len() != want.len()).then(|| got.len().min(want.len())))
}

/// The END-only stream the vendor writes for nothing to draw: its first byte is END. The vendor leaves bytes 1..3 uninitialised (the oracle shows 0x80 in byte 1 once), so only the opcode and the length are checked.
fn is_end_only(result: io::Result<Vec<u8>>) -> bool {
    matches!(result, Ok(ref bytes) if bytes.len() == 4 && bytes[0] == 0x00)
}

#[test]
fn every_fixture_matches_its_vendor_golden_bit_for_bit() {
    let mut matched = 0;
    let mut refused = 0;
    for &(name, points, cap_code, join_code, width_bits, miter_bits, _bbox, _path_length) in
        FIXTURES_STROKE
    {
        let (Some(cap), Some(join)) = (cap_of(cap_code), join_of(join_code)) else {
            panic!("fixture {name}: unknown cap or join code");
        };
        // The oracle's open fixtures are the `o_` ones (add_end 1); the others are closed (add_end 0).
        let subpath = if name.starts_with("o_") {
            Subpath::Open
        } else {
            Subpath::Closed
        };
        let result = outline(
            &points_from_bits(points),
            f32::from_bits(width_bits),
            cap,
            join,
            f32::from_bits(miter_bits),
            subpath,
        );
        if cap == Cap::Round || join == Join::Round {
            assert!(
                matches!(
                    name,
                    "h_round" | "poly_round" | "o_h_round" | "o_poly_round"
                ),
                "fixture {name} is not a round fixture"
            );
            assert_eq!(
                error_kind(result),
                Some(io::ErrorKind::Unsupported),
                "{name}"
            );
            refused += 1;
            continue;
        }
        let Some(want) = golden_for(name) else {
            panic!("fixture {name} has no golden");
        };
        let got = match result {
            Ok(bytes) => bytes,
            Err(error) => panic!("{name}: outline failed: {error}"),
        };
        assert!(
            got.as_slice() == want,
            "{name}: {} bytes against {} in the golden, first difference at byte {:?}",
            got.len(),
            want.len(),
            first_difference(&got, want),
        );
        matched += 1;
    }
    assert_eq!(matched, 30, "every supported fixture must be checked");
    assert_eq!(refused, 4, "every round fixture must be refused");
}

#[test]
fn round_cap_and_round_join_are_refused_for_both_subpaths() {
    let points = [(2.0, 8.0), (13.0, 8.0), (13.0, 12.0)];
    for subpath in [Subpath::Open, Subpath::Closed] {
        assert_eq!(
            error_kind(outline(&points, 1.0, Cap::Round, Join::Miter, 4.0, subpath)),
            Some(io::ErrorKind::Unsupported)
        );
        assert_eq!(
            error_kind(outline(&points, 1.0, Cap::Butt, Join::Round, 4.0, subpath)),
            Some(io::ErrorKind::Unsupported)
        );
    }
}

#[test]
fn non_positive_or_non_finite_width_is_invalid_input() {
    let points = [(2.0, 8.0), (13.0, 8.0)];
    for subpath in [Subpath::Open, Subpath::Closed] {
        for width in [0.0, -1.0, f32::NAN, f32::INFINITY] {
            assert_eq!(
                error_kind(outline(
                    &points,
                    width,
                    Cap::Butt,
                    Join::Miter,
                    4.0,
                    subpath
                )),
                Some(io::ErrorKind::InvalidInput),
                "width {width}"
            );
        }
    }
}

#[test]
fn miter_limit_below_one_behaves_as_a_bevel() {
    // The limit is clamped to 1, and every real corner has a miter ratio of at least 1. So the miter always falls back to a bevel.
    let points = [(2.0, 2.0), (10.0, 2.0), (10.0, 12.0)];
    let limited = outline(&points, 2.0, Cap::Butt, Join::Miter, 0.25, Subpath::Closed);
    let bevel = outline(&points, 2.0, Cap::Butt, Join::Bevel, 4.0, Subpath::Closed);
    assert_eq!(limited.ok(), bevel.ok());
}

#[test]
fn caps_do_not_change_a_closed_outline() {
    // The closed subpath draws no end caps. Every closed fixture pair differs only in cap, and the goldens agree.
    let points = [(2.0, 2.0), (10.0, 2.0), (10.0, 12.0)];
    let butt = outline(&points, 2.0, Cap::Butt, Join::Miter, 4.0, Subpath::Closed);
    let square = outline(&points, 2.0, Cap::Square, Join::Miter, 4.0, Subpath::Closed);
    assert_eq!(butt.ok(), square.ok());
}

#[test]
fn caps_change_an_open_outline() {
    // The open line has end caps: SQUARE extends it, so it differs from BUTT (oracle: o_h_butt vs o_h_square).
    let points = [(2.0, 8.0), (13.0, 8.0)];
    let butt = outline(&points, 1.0, Cap::Butt, Join::Miter, 4.0, Subpath::Open);
    let square = outline(&points, 1.0, Cap::Square, Join::Miter, 4.0, Subpath::Open);
    assert_ne!(butt.ok(), square.ok());
}

#[test]
fn a_repeated_point_is_dropped_as_the_vendor_drops_it() {
    // `_add_point_to_point_list` skips a LINE equal to the last point. The triangle with its corner repeated is the poly_miter golden's input (oracle run: x_dedupe_mid).
    let repeated = [(2.0, 2.0), (10.0, 2.0), (10.0, 2.0), (10.0, 12.0)];
    assert_eq!(
        outline(&repeated, 2.0, Cap::Butt, Join::Miter, 4.0, Subpath::Closed)
            .ok()
            .as_deref(),
        Some(GEOM_POLY_MITER)
    );
}

#[test]
fn a_point_within_the_vendor_epsilon_of_the_last_is_dropped() {
    // One ulp above (10, 2): the ratio test (1.2e-7 < 1e-6) drops it (oracle run: x_ulp).
    let one_ulp = f32::from_bits(2.0_f32.to_bits() + 1);
    let near = [(2.0, 2.0), (10.0, 2.0), (10.0, one_ulp), (10.0, 12.0)];
    assert_eq!(
        outline(&near, 2.0, Cap::Butt, Join::Miter, 4.0, Subpath::Closed)
            .ok()
            .as_deref(),
        Some(GEOM_POLY_MITER)
    );
    // Two hundredths of a unit above is kept: the ratio test does not drop it (oracle run: x_kept, 196 bytes).
    let kept = [(2.0, 2.0), (10.0, 2.0), (10.0, 2.02), (10.0, 12.0)];
    assert_eq!(
        outline(&kept, 2.0, Cap::Butt, Join::Miter, 4.0, Subpath::Closed)
            .ok()
            .map(|bytes| bytes.len()),
        Some(196)
    );
}

#[test]
fn a_lone_point_draws_nothing() {
    // `_flatten_path` deletes a subpath that is a MOVE with no LINE, so only END is written (oracle run: x_single_square).
    assert!(is_end_only(outline(
        &[(2.0, 8.0)],
        1.0,
        Cap::Square,
        Join::Miter,
        4.0,
        Subpath::Closed
    )));
}

#[test]
fn a_collapsed_subpath_draws_a_square_only_for_square_caps() {
    // Two equal points: one point remains, and `_add_zero_length_stroke_sub_path` draws it (oracle run: x_pair_square, x_pair_butt).
    let points = [(2.0, 8.0), (2.0, 8.0)];
    assert!(is_end_only(outline(
        &points,
        1.0,
        Cap::Butt,
        Join::Miter,
        4.0,
        Subpath::Closed
    )));
    let square = outline(&points, 1.0, Cap::Square, Join::Miter, 4.0, Subpath::Closed).ok();
    let expected: Vec<u8> = [
        vec![2, 0, 0, 0],
        2.5_f32.to_le_bytes().to_vec(),
        7.5_f32.to_le_bytes().to_vec(),
        vec![4, 0, 0, 0],
        2.5_f32.to_le_bytes().to_vec(),
        8.5_f32.to_le_bytes().to_vec(),
        vec![4, 0, 0, 0],
        1.5_f32.to_le_bytes().to_vec(),
        8.5_f32.to_le_bytes().to_vec(),
        vec![4, 0, 0, 0],
        1.5_f32.to_le_bytes().to_vec(),
        7.5_f32.to_le_bytes().to_vec(),
        vec![0, 0, 0, 0],
    ]
    .concat();
    assert_eq!(square, Some(expected));
}
